package webui

// stylesSettings is the control-settings workspace (v31) and its mobile-settings pass (v32).
// Each const holds one contiguous slice of the stylesheet; the global order is
// reassembled in styles_desktop_app.go. Keep every const byte-identical to the
// corresponding line range of the original single-const layout.
const stylesSettings = `/* Control settings v31: server-persisted operational defaults. */
.settings-workspace{width:100%;max-width:1080px;margin:0 auto}.settings-hero{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:16px;padding:4px 2px}.settings-hero h2{margin:4px 0;font-size:28px;letter-spacing:-.035em}.settings-hero>div>p:last-child{color:var(--muted);font-size:12px}.settings-persistence{min-width:190px;display:grid;grid-template-columns:8px 1fr;align-items:center;gap:2px 8px;padding:10px 13px;border:1px solid color-mix(in srgb,var(--green) 24%,var(--line));border-radius:12px;background:var(--green-soft);color:var(--green)}.settings-persistence i{grid-row:1/3;width:8px;height:8px;border-radius:50%;background:var(--green)}.settings-persistence b,.settings-persistence small{display:block}.settings-persistence b{font-size:11px}.settings-persistence small{font-size:9px}.settings-form{display:grid;gap:14px}.settings-section{scroll-margin-top:76px;border:1px solid transparent;border-radius:var(--radius-card);background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.settings-section>header{display:grid;grid-template-columns:42px minmax(0,1fr);align-items:start;gap:13px;padding:18px 20px;border-bottom:1px solid var(--line);background:linear-gradient(135deg,var(--surface),color-mix(in srgb,var(--accent-soft) 38%,var(--surface)))}.settings-section-number{width:42px;height:42px;display:grid;place-items:center;border-radius:12px;background:var(--accent-soft);color:var(--accent);font-size:10px;font-weight:800}.settings-section h3{font-size:17px;letter-spacing:-.02em}.settings-section header p{margin-top:3px;color:var(--muted);font-size:10px}.settings-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;padding:20px}.settings-grid.one-column{grid-template-columns:minmax(260px,520px)}.settings-field{display:grid;gap:6px;align-content:start}.settings-field>span{font-size:11px;font-weight:750}.settings-field input,.settings-field select{width:100%}.settings-field small{color:var(--muted);font-size:9px;line-height:1.55}.settings-hint{margin:0;color:var(--muted);font-size:9px;line-height:1.7}.settings-hint code{color:var(--ink-2)}.audit-list{display:grid;gap:6px;margin:0;padding:20px;list-style:none}.audit-list li{display:grid;grid-template-columns:118px 86px minmax(0,1fr) minmax(0,1.4fr) 110px;align-items:center;gap:10px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface-2)}.audit-list time{color:var(--muted);font-size:9px}.audit-list .audit-action{font-size:10px;font-weight:750}.audit-list code{overflow:hidden;color:var(--ink-2);font-size:9px;text-overflow:ellipsis;white-space:nowrap}.audit-list small{overflow:hidden;color:var(--muted);font-size:9px;text-overflow:ellipsis;white-space:nowrap}.audit-list em{overflow:hidden;color:var(--muted);font-size:8px;font-style:normal;text-align:right;text-overflow:ellipsis;white-space:nowrap}.settings-savebar{position:sticky;z-index:20;bottom:0;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 16px;border:1px solid var(--line);border-radius:14px;background:color-mix(in srgb,var(--surface) 94%,transparent);box-shadow:0 -14px 36px -30px rgba(15,18,38,.75);backdrop-filter:blur(14px)}.settings-savebar b,.settings-savebar small{display:block}.settings-savebar b{font-size:11px}.settings-savebar small{margin-top:2px;color:var(--muted);font-size:9px}.settings-savebar>div:last-child{display:flex;gap:8px}.settings-saved-state{padding:5px 9px;border-radius:12px;background:var(--green-soft);color:var(--green);font-size:9px;font-weight:700}.settings-callout>span small{display:inline;font-size:10px}
/* Mobile settings v32: keep actions in document flow so every field remains reachable. */
@media(max-width:820px){.app-dock{grid-template-columns:repeat(7,1fr)}.page-settings .context-sidebar{padding-block:8px}.settings-hero{align-items:flex-start;flex-direction:column;gap:12px}.settings-persistence{min-width:0}.settings-grid{grid-template-columns:1fr;padding:16px}.settings-grid.one-column{grid-template-columns:1fr}.settings-section>header{padding:16px}.settings-savebar{position:static;bottom:auto;align-items:stretch;flex-direction:column}.settings-savebar>div:last-child{display:grid;grid-template-columns:1fr 1fr}.settings-savebar .button{min-width:0}.page-settings .workspace-main{padding-bottom:20px}}
@media(max-width:420px){.app-dock{left:6px;right:6px}.dock-nav a,.dock-tools button{gap:1px}.dock-nav svg,.dock-tools svg{width:17px;height:17px}.settings-savebar>div:last-child{grid-template-columns:1fr}}

`
